"""Summarize paired scenarios, excluding zero baselines from relative means."""
import statistics,json
from collections import defaultdict
from pathlib import Path
from generate import read_csv,write_csv
R=Path(__file__).resolve().parent
rows=read_csv(R/'comparison_final.csv'); previous=read_csv(R/'comparison_previous_version.csv'); types=read_csv(R/'ml_scenario_results.csv')
n={(r['scenario_id'],r['strategy']):r for r in rows}; old={(r['scenario_id'],r['strategy']):r for r in previous}
ids=sorted({r['scenario_id'] for r in rows})
if len(ids)!=114 or len(n)!=228 or set(n)!=set(old): raise ValueError('Expected 114 matching paired scenarios in both versions')
pairs=[]
for sid in ids:
 f,o=n[sid,'FCFS'],n[sid,'OPTIMIZED']; a,b=float(f['delivered_on_time_t']),float(o['delivered_on_time_t']); ft,ot=float(f['delivered_total_t']),float(o['delivered_total_t'])
 pairs.append(dict(scenario_id=sid,fcfs_on_time_t=a,optimized_on_time_t=b,on_time_delta_t=round(b-a,3),on_time_delta_pct=round(100*(b-a)/a,6) if a else '',fcfs_total_t=ft,optimized_total_t=ot,total_delta_t=round(ot-ft,3),fcfs_trips=int(f['completed_trips']),optimized_trips=int(o['completed_trips']),violations=int(f['violations'])+int(o['violations'])))
write_csv(R/'comparison_pairs.csv',pairs)
before=[]
for key in sorted(n):
 p,q=old[key],n[key]
 before.append(dict(scenario_id=key[0],strategy=key[1],before_on_time_t=p['delivered_on_time_t'],after_on_time_t=q['delivered_on_time_t'],change_on_time_t=round(float(q['delivered_on_time_t'])-float(p['delivered_on_time_t']),3),before_total_t=p['delivered_total_t'],after_total_t=q['delivered_total_t'],change_total_t=round(float(q['delivered_total_t'])-float(p['delivered_total_t']),3),before_trips=p['completed_trips'],after_trips=q['completed_trips']))
write_csv(R/'comparison_before_after.csv',before)
t=defaultdict(dict)
for x in types:
 k=(x['scenario_id'],x['cargo_type']); t[k][x['strategy']]=x
if len(t)!=len(ids)*4 or any(set(v)!=set(('FCFS','OPTIMIZED')) for v in t.values()): raise ValueError('Cargo-type rows missing')
bytype=[]
for typ in sorted({k[1] for k in t}):
 group=[v for (sid,k),v in t.items() if k==typ]
 bytype.append(dict(cargo_type=typ,fcfs_on_time_t=statistics.mean(float(v['FCFS']['on_time_t']) for v in group),optimized_on_time_t=statistics.mean(float(v['OPTIMIZED']['on_time_t']) for v in group),fcfs_total_t=statistics.mean(float(v['FCFS']['delivered_t']) for v in group),optimized_total_t=statistics.mean(float(v['OPTIMIZED']['delivered_t']) for v in group)))
opt_before=[x for x in before if x['strategy']=='OPTIMIZED']
d=[x['on_time_delta_t'] for x in pairs]; td=[x['total_delta_t'] for x in pairs]; pct=[x['on_time_delta_pct'] for x in pairs if x['on_time_delta_pct']!='']; wins=sum(v>0 for v in d); ties=sum(v==0 for v in d); losses=sum(v<0 for v in d); violations=sum(x['violations'] for x in pairs)
report=['# Итоговая сводка: версия 2.1.0','', 'Это **планирование при полной информации о заданном сценарии**, а не прогноз работы реального диспетчера или доказательство безопасности судоходства. Исходные входы не менялись.','', '## Цель и эксперимент','', 'Цель лексикографическая: максимум тонн вовремя, затем максимум всех доставленных тонн, затем минимум числа рейсов. Просроченные рейсы допустимы при соблюдении всех ограничений и проходят тот же аудит. Жадное ранжирование и ограниченный локальный поиск не гарантируют глобального оптимума.','', '114 пар: 108 исходных вариантов (3 seed × 4 внешних условия × 3 глубины × 3 даты готовности) и 6 вариантов сокращённого или удвоенного флота. Один и тот же набор заявок и условий используется для FCFS и OPTIMIZED. Средние ниже невзвешенные: каждый сценарий имеет один голос. Относительная разность вычисляется отдельно для каждой пары как 100 × (OPTIMIZED − FCFS) / FCFS; пары с нулевой доставкой FCFS исключаются из среднего процента.','', '## Сравнение OPTIMIZED с FCFS','', '| Показатель | Значение |','|---|---:|',f'| Средний прирост вовремя, т | {statistics.mean(d):.3f} |',f'| Медианный прирост вовремя, т | {statistics.median(d):.3f} |',f'| Средний относительный прирост вовремя, % | {statistics.mean(pct):.3f} |' if pct else '| Средний относительный прирост вовремя, % | не определяется |',f'| Нулевой FCFS, исключено из среднего процента | {len(pairs)-len(pct)} |',f'| Минимальный / максимальный прирост вовремя, т | {min(d):.3f} / {max(d):.3f} |',f'| Среднее изменение общего тоннажа, т | {statistics.mean(td):.3f} |',f'| Победы / ничьи / поражения по тоннам вовремя | {wins} / {ties} / {losses} |',f'| Нарушения аудита в 228 расписаниях | {violations} |','', 'Все пары с абсолютным и относительным эффектом находятся в `comparison_pairs.csv`; пустой процент означает нулевой FCFS. `comparison_final.csv` содержит исходные показатели каждой стратегии, а `comparison_before_after.csv` сравнивает обе стратегии с предыдущей версией по тем же 114 входам.','', '## Виды груза','', 'Средняя доставка на сценарий, т; общая доставка включает опоздавшие партии. Показываются сценарные типы, не фактические объёмы завоза.','', '| Тип | FCFS вовремя | OPTIMIZED вовремя | FCFS всего | OPTIMIZED всего |','|---|---:|---:|---:|---:|']
for x in bytype: report.append(f"| {x['cargo_type']} | {x['fcfs_on_time_t']:.3f} | {x['optimized_on_time_t']:.3f} | {x['fcfs_total_t']:.3f} | {x['optimized_total_t']:.3f} |")
report+=['','Полная таблица по каждому сценарию, стратегии и типу — `ml_scenario_results.csv`. В этих опытах средняя общая доставка продовольствия у OPTIMIZED ниже, чем у FCFS: целевая функция не задаёт для него отдельного приоритета или минимального объёма. Это ограничение важно учитывать при постановке задачи для реального завоза.','', '## Изменение относительно предыдущей версии','', f"Для OPTIMIZED среднее изменение своевременной доставки: {statistics.mean(float(x['change_on_time_t']) for x in opt_before):.3f} т; общей доставки: {statistics.mean(float(x['change_total_t']) for x in opt_before):.3f} т на сценарий. Общая доставка выросла в {sum(float(x['change_total_t'])>0 for x in opt_before)} случаях, не изменилась в {sum(float(x['change_total_t'])==0 for x in opt_before)} и уменьшилась в {sum(float(x['change_total_t'])<0 for x in opt_before)}.",'', '## Информация и ограничения','', 'Заявки целиком, их сроки и даты готовности, доступность флота, весь календарь глубин и закрытий заданы заранее и доступны программе до расчёта. Обе стратегии используют будущие условия маршрута при проверке рейса. OPTIMIZED при выборе на день рассматривает только партии, готовые до конца этого дня, и может ожидать их готовности; FCFS применяет очередь по готовности. Это не тест online-диспетчеризации и не сравнение прогнозов. Знание будущих глубин в этом опыте точное внутри модели; в реальности такого знания не подтверждено.','', 'Проверяются грузоподъёмность, модельные осадки и глубины на каждом участке/дне, закрытия, сроки и продолжительность обработки и движения, занятость буксира и баржи, возврат в окно навигации. Не моделируются фактическая гидрология, погода и лёд, тяга/класс судов, общая очередь причалов, разрешения, расходы и ожидание в пути. Маршрут — заданная линейная цепочка.','', 'Нормативная длина и некоторые общеречные данные имеют источники; назначение грузов пилотному маршруту, состав и параметры флота, ежедневные глубины, партии и сроки сценарные. Плановые ориентиры не подтверждены первичным документом. Общеречные агрегаты не калибруют рейсы пилота. Подробности — `sources.md` и `assumptions.md`.','', '## Верификация и версия','', 'Аудит выполняется при построении каждого расписания и прерывает расчёт при нарушении. Полный повторный запуск сравнивает сохранённые расписания и метрики; результат — `reproducibility_check.json`. Имеются тесты трёх критериев, поздней доставки, закрытий и ресурсов; четыре малые задачи сравниваются с полным перебором. `ALGORITHM_VERSION.json` фиксирует версию и хэши исходного кода; каталог не является Git-репозиторием.','', 'Указанные результаты не подтверждают фактический эффект в Якутии в 2026 году. Для практического планирования нужны подтверждённые заявки, флот, характеристики и ограничения на даты реальных рейсов.','']
(R/'optimization_report.md').write_text('\n'.join(report),encoding='utf-8')
print(json.dumps({'pairs':len(pairs),'mean_delta_t':statistics.mean(d),'median_delta_t':statistics.median(d),'mean_delta_pct':statistics.mean(pct) if pct else None,'pct_excluded':len(pairs)-len(pct),'min_delta_t':min(d),'max_delta_t':max(d),'mean_total_delta_t':statistics.mean(td),'wins':wins,'ties':ties,'losses':losses,'violations':violations,'types':bytype},ensure_ascii=False,indent=2))
